<script setup>
import { Link, useForm } from '@inertiajs/vue3';
import AssessmentLayout from './AssessmentLayout.vue';
const props = defineProps({ post: Object, categories: Array });
const form = useForm({ title: props.post?.title || '', category: props.post?.category || props.categories[0], version_label: props.post?.version_label || '', excerpt: props.post?.excerpt || '', body: props.post?.body || '', action_label: props.post?.action_label || '', action_url: props.post?.action_url || '', cover_image: null });
const save = () => form.transform(data => props.post ? {...data,_method:'put'} : data).post(props.post ? route('admin.doopnews.update',props.post.slug) : route('admin.doopnews.store'), {forceFormData:true});
</script>
<template><AssessmentLayout :title="post ? 'Edit DoopNews' : 'Tulis DoopNews'" subtitle="Susun berita yang akan dibaca komunitas." breadcrumb="Komunitas & pengguna"><div class="layout"><form class="panel" @submit.prevent="save"><div class="fields"><label class="wide">Judul<input v-model="form.title" maxlength="160" required /><span class="error">{{ form.errors.title }}</span></label><label>Kategori<select v-model="form.category"><option v-for="category in categories" :key="category" :value="category">{{ category }}</option></select></label><label>Label versi<input v-model="form.version_label" maxlength="80" /></label><label class="wide">Ringkasan<textarea v-model="form.excerpt" rows="3" maxlength="500" /></label><label class="wide">Isi berita<textarea v-model="form.body" rows="14" required /><span class="error">{{ form.errors.body }}</span></label><label>Label tombol<input v-model="form.action_label" /></label><label>URL tombol<input v-model="form.action_url" type="url" /></label><label class="wide">Gambar sampul<input type="file" accept="image/*" @change="form.cover_image=$event.target.files[0]" /><span class="error">{{ form.errors.cover_image }}</span></label></div><div class="actions"><button class="primary" :disabled="form.processing">{{ post ? 'Simpan perubahan' : 'Publikasikan berita' }}</button><Link class="secondary" :href="route('redesign.doopnews')">Kembali</Link></div></form><aside><div class="panel"><h2>Pratinjau</h2><img v-if="post?.cover_image_path" :src="'/storage/'+post.cover_image_path" alt="Sampul saat ini" style="max-width:100%;border-radius:8px" /><p><strong>{{ form.title || 'Judul berita' }}</strong></p><p class="muted">{{ form.excerpt || 'Ringkasan berita akan tampil di sini.' }}</p></div></aside></div></AssessmentLayout></template>
